const localizedCopy=JSON.parse(document.querySelector('#localized-copy').textContent);
const localForm=document.querySelector('[data-locale-quote]');
if(localForm){localForm.querySelector('[type=submit]').disabled=false;const intent=new URLSearchParams(location.search).get('intent');if(['home','clinic','distributor'].includes(intent))localForm.querySelector('[name=buyer]').selectedIndex=['home','clinic','distributor'].indexOf(intent);localForm.addEventListener('submit',e=>{e.preventDefault();if(!localForm.reportValidity())return;const d=new FormData(localForm),at=inquiryAttribution();addMetric(location.pathname,'emailDrafts');const fields=['buyer','name','email','country','organization','quantity','notes'];const request=['QuickMind | '+localizedCopy.quote, 'Language: '+document.documentElement.lang, ...fields.map(key=>localizedCopy[key]+' ('+key+'): '+(d.get(key)||'—')),'Source page: '+at.page,'Source entry: '+at.cta,'Page reference: '+at.reference,'Campaign: '+JSON.stringify(at.utm)].join('\n');const result=document.querySelector('#local-result');result.hidden=false;document.querySelector('#local-request').value=request;document.querySelector('#local-mail').href='mailto:yiweiinc99@gmail.com?subject='+encodeURIComponent('QuickMind quotation | '+document.documentElement.lang)+'&body='+encodeURIComponent(request);result.scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('#local-request').focus();});document.querySelector('#local-copy').addEventListener('click',async()=>{const request=document.querySelector('#local-request');try{await navigator.clipboard.writeText(request.value);document.querySelector('#local-status').textContent=localizedCopy.copy+' ✓'}catch{request.focus();request.select()}})}
document.querySelector('.menu-toggle').addEventListener('click',e=>{const open=document.querySelector('header nav').classList.toggle('open');e.target.setAttribute('aria-expanded',String(open))});
tagPageSources();mountPayPalButtons();updateLanguageLinks();
